window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["uber"]={html:"<div class=\"own-uber\">\n  <a class=\"ub-skip\" href=\"#ubMain\">Skip to content</a>\n\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"ub-nav\" id=\"ubNav\">\n    <div class=\"ub-nav-in\">\n      <a class=\"ub-brand\" href=\"#ubMain\" aria-label=\"Northwind home\">Northwind</a>\n      <nav class=\"ub-nav-links\" aria-label=\"Primary\">\n        <a href=\"#ubProducts\">Products</a>\n        <a href=\"#ubWhy\">Why Northwind</a>\n        <a href=\"#ubPricing\">Pricing</a>\n        <a href=\"#ubFaq\">Support</a>\n      </nav>\n      <div class=\"ub-nav-actions\">\n        <a class=\"ub-btn ub-btn-secondary ub-btn-sm\" href=\"#\">Log in</a>\n        <a class=\"ub-btn ub-btn-primary ub-btn-sm\" href=\"#ubPricing\">Sign up</a>\n        <button class=\"ub-burger\" type=\"button\" aria-label=\"Menu\" data-ub-menu aria-expanded=\"false\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n        </button>\n      </div>\n    </div>\n    <div class=\"ub-drawer\" hidden data-ub-drawer>\n      <a href=\"#ubProducts\">Products</a><a href=\"#ubWhy\">Why Northwind</a><a href=\"#ubPricing\">Pricing</a><a href=\"#ubFaq\">Support</a>\n    </div>\n  </header>\n\n  <main id=\"ubMain\">\n    <!-- ── HERO — white band with request form ────────────────────────── -->\n    <section class=\"ub-hero\">\n      <div class=\"ub-wrap ub-hero-in\">\n        <div class=\"ub-hero-copy\">\n          <h1 class=\"ub-display-xxl\">Go anywhere with your operations data.</h1>\n          <p class=\"ub-lead\">Northwind is the operations analytics layer for ride, delivery, and freight teams. One black-and-white surface for regions, throughput, and the numbers that move the city.</p>\n          <div class=\"ub-tabs\" role=\"tablist\" aria-label=\"Workspace\">\n            <button class=\"ub-tab on\" type=\"button\" role=\"tab\" aria-selected=\"true\">Operations</button>\n            <button class=\"ub-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\">Revenue</button>\n          </div>\n        </div>\n        <div class=\"ub-request-card\" aria-label=\"Northwind request form\">\n          <div class=\"ub-req-row\">\n            <span class=\"ub-req-ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"10\" r=\"3\"/><path d=\"M12 2a8 8 0 0 0-8 8c0 6 8 12 8 12s8-6 8-12a8 8 0 0 0-8-8Z\"/></svg></span>\n            <span><span class=\"ub-req-lab\">Region</span><span class=\"ub-req-val\">Metro Manila</span></span>\n          </div>\n          <div class=\"ub-req-row\">\n            <span class=\"ub-req-ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 12h16M14 6l6 6-6 6\"/></svg></span>\n            <span><span class=\"ub-req-lab\">Metric</span><span class=\"ub-req-val\">On-time throughput</span></span>\n          </div>\n          <div class=\"ub-req-row ub-req-when\">\n            <span class=\"ub-req-ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 9h16M9 3v4M15 3v4\"/></svg></span>\n            <span><span class=\"ub-req-lab\">Window</span><span class=\"ub-req-val\">This quarter</span></span>\n          </div>\n          <button class=\"ub-btn ub-btn-primary ub-btn-wide\" type=\"button\">See prices</button>\n        </div>\n      </div>\n      <div class=\"ub-wrap ub-chips\" id=\"ubChips\" aria-label=\"Quick starts\"></div>\n    </section>\n\n    <!-- ── PROMO CARDS — alternating, illustrated ─────────────────────── -->\n    <section class=\"ub-section\" id=\"ubProducts\">\n      <div class=\"ub-wrap\">\n        <div class=\"ub-sec-head\">\n          <p class=\"ub-eyebrow\">Products</p>\n          <h2 class=\"ub-display-xl\">Plan for the whole operation</h2>\n        </div>\n\n        <article class=\"ub-promo\">\n          <div class=\"ub-promo-art ub-art-riders\" aria-hidden=\"true\">\n            <div class=\"ub-art-tile\"><span class=\"ub-art-num\">98.4%</span><span class=\"ub-art-lab\">On-time throughput · six regions</span>\n              <svg viewBox=\"0 0 300 90\" preserveAspectRatio=\"none\"><path d=\"M0 72 L43 64 L86 68 L129 44 L172 50 L215 26 L258 32 L300 14\" fill=\"none\" stroke=\"#000\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n            </div>\n          </div>\n          <div class=\"ub-promo-copy\">\n            <h3 class=\"ub-display-md\">Every region on one ledger</h3>\n            <p class=\"ub-body\">Compare throughput and revenue across six regions at a glance. A change in one shows up in the others instantly — no reconciliation call.</p>\n            <a class=\"ub-btn ub-btn-primary\" href=\"#ubPricing\">Get started</a>\n          </div>\n        </article>\n\n        <article class=\"ub-promo ub-promo-rev\">\n          <div class=\"ub-promo-art ub-art-drivers\" aria-hidden=\"true\">\n            <div class=\"ub-art-tile ub-art-dark\"><span class=\"ub-art-num\">$48.2k</span><span class=\"ub-art-lab\">Revenue · this week</span>\n              <div class=\"ub-bars\" aria-hidden=\"true\"><i style=\"height:38%\"></i><i style=\"height:62%\"></i><i style=\"height:50%\"></i><i style=\"height:78%\"></i><i style=\"height:66%\"></i><i style=\"height:92%\"></i></div>\n            </div>\n          </div>\n          <div class=\"ub-promo-copy\">\n            <h3 class=\"ub-display-md\">Revenue and throughput, one board</h3>\n            <p class=\"ub-body\">Keep delivery economics next to the work itself. Northwind pins revenue to the same ledger as the shipments that produced it.</p>\n            <a class=\"ub-btn ub-btn-subtle\" href=\"#ubWhy\">Learn more</a>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── BLACK MID-PAGE PROMO BAND ──────────────────────────────────── -->\n    <section class=\"ub-dark-band\" id=\"ubWhy\">\n      <div class=\"ub-wrap ub-dark-in\">\n        <div class=\"ub-promo-art ub-art-dark-illus\" aria-hidden=\"true\">\n          <div class=\"ub-art-tile ub-art-onblack\"><span class=\"ub-art-num\">6</span><span class=\"ub-art-lab\">regions, live right now</span>\n            <div class=\"ub-map\" aria-hidden=\"true\"><span class=\"ub-map-dot\" style=\"left:24%;top:38%\"></span><span class=\"ub-map-dot\" style=\"left:52%;top:60%\"></span><span class=\"ub-map-dot\" style=\"left:74%;top:30%\"></span></div>\n          </div>\n        </div>\n        <div class=\"ub-dark-copy\">\n          <h2 class=\"ub-display-xxl\">Drive decisions when you want.</h2>\n          <p class=\"ub-body-on-dark\">Northwind runs your dashboards, alerts, and forecasts on one schedule you set. Bring the whole operation online and read it from anywhere.</p>\n          <div class=\"ub-dark-actions\">\n            <a class=\"ub-btn ub-btn-secondary\" href=\"#ubPricing\">Start free</a>\n            <a class=\"ub-btn ub-btn-ghost-on-dark\" href=\"#ubProducts\">See the product</a>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── ANNUAL SHOWCASE CARD ───────────────────────────────────────── -->\n    <section class=\"ub-section\">\n      <div class=\"ub-wrap\">\n        <div class=\"ub-showcase\" aria-label=\"Northwind operations review\">\n          <div class=\"ub-showcase-art\" aria-hidden=\"true\">\n            <span class=\"ub-showcase-year\">2026</span>\n          </div>\n          <div class=\"ub-showcase-copy\">\n            <p class=\"ub-eyebrow-on-dark\">Annual review</p>\n            <h2 class=\"ub-display-lg\">The operations report, all in one place.</h2>\n            <p class=\"ub-body-on-dark\">Every region, every quarter, every dollar — published as a living board instead of a PDF.</p>\n            <a class=\"ub-app-pill\" href=\"#\">Open the review</a>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FAQ ────────────────────────────────────────────────────────── -->\n    <section class=\"ub-section\" id=\"ubPricing\">\n      <div class=\"ub-wrap ub-faq-wrap\">\n        <div class=\"ub-faq-head\">\n          <p class=\"ub-eyebrow\">Questions</p>\n          <h2 class=\"ub-display-xl\">Everything you asked</h2>\n          <a class=\"ub-btn ub-btn-subtle\" href=\"#ubFaq\">Visit support</a>\n        </div>\n        <div class=\"ub-faq\" id=\"ubFaq\"></div>\n      </div>\n    </section>\n\n    <!-- ── APP DOWNLOAD PILLS ─────────────────────────────────────────── -->\n    <section class=\"ub-downloads\">\n      <div class=\"ub-wrap ub-dl-in\">\n        <div><p class=\"ub-display-md\">Download the Operations app</p><a class=\"ub-app-pill\" href=\"#\">Get it on iOS & Android</a></div>\n        <div><p class=\"ub-display-md\">Download the Field app</p><a class=\"ub-app-pill\" href=\"#\">Get it on iOS & Android</a></div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER — black ─────────────────────────────────────────────── -->\n  <footer class=\"ub-foot\">\n    <div class=\"ub-wrap\">\n      <p class=\"ub-foot-word\">Northwind</p>\n      <div class=\"ub-foot-grid\">\n        <div><p class=\"ub-foot-head\">Product</p><a href=\"#ubProducts\">Dashboards</a><a href=\"#ubWhy\">Alerts</a><a href=\"#ubPricing\">Pricing</a></div>\n        <div><p class=\"ub-foot-head\">Company</p><a href=\"#\">About</a><a href=\"#\">Newsroom</a><a href=\"#\">Careers</a></div>\n        <div><p class=\"ub-foot-head\">Support</p><a href=\"#ubFaq\">Help center</a><a href=\"#\">Status</a></div>\n        <div><p class=\"ub-foot-head\">Legal</p><a class=\"ub-foot-link\" href=\"#\">Privacy</a><a class=\"ub-foot-link\" href=\"#\">Terms</a></div>\n      </div>\n      <p class=\"ub-foot-fine\">© 2026 · Sample data — showcase only</p>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ UBER — Northwind operations analytics, built in Uber's real page grammar ══\n   Black-and-white duet, pill (999px) on every interactive element, 16px cards,\n   UberMove display + UberMoveText body, editorial 4:3 illustration frames. Scoped\n   under `.own-uber`. */\n\n.own-uber {\n  --primary: #000000;\n  --on-primary: #ffffff;\n  --ink: #000000;\n  --body: #5e5e5e;\n  --mute: #afafaf;\n  --hairline-mid: #4b4b4b;\n  --canvas: #ffffff;\n  --canvas-soft: #efefef;\n  --canvas-softer: #f3f3f3;\n  --surface-pressed: #e2e2e2;\n  --link: #0000ee;\n  --on-dark: #ffffff;\n  --black-elevated: #282828;\n\n  --f-display: 'UberMove', 'Inter', 'Geist', system-ui, 'Helvetica Neue', Arial, sans-serif;\n  --f-text: 'UberMoveText', 'Inter', 'Geist', system-ui, 'Helvetica Neue', Arial, sans-serif;\n\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-pill: 999px;\n  --r-pill-tab: 36px;\n  --gut: clamp(16px, 4.6cqi, 32px);\n  --sec: clamp(40px, 6cqi, 64px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--f-text);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n\n.own-uber *, .own-uber *::before, .own-uber *::after { box-sizing: border-box; }\n.own-uber p { margin: 0; }\n.own-uber h1, .own-uber h2, .own-uber h3 { margin: 0; }\n.own-uber a { color: inherit; text-decoration: none; }\n.own-uber img, .own-uber svg { display: block; }\n.own-uber button { font: inherit; }\n.own-uber :focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n.own-uber .ub-dark-band :focus-visible, .own-uber .ub-foot :focus-visible, .own-uber .ub-showcase :focus-visible { outline-color: #fff; }\n\n.own-uber .ub-wrap { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 var(--gut); }\n\n.own-uber .ub-skip {\n  position: absolute; left: 12px; top: -60px; z-index: 60;\n  padding: 10px 16px; border-radius: var(--r-md); background: var(--ink); color: var(--on-dark);\n  font-weight: 500; transition: top .2s;\n}\n.own-uber .ub-skip:focus { top: 12px; }\n\n/* ── type — sentence-case, weight 700 display ────────────────────────── */\n.own-uber .ub-display-xxl { font-family: var(--f-display); font-size: clamp(34px, 5.4cqi, 52px); font-weight: 700; line-height: 1.23; letter-spacing: -.5px; }\n.own-uber .ub-display-xl { font-family: var(--f-display); font-size: clamp(28px, 3.8cqi, 36px); font-weight: 700; line-height: 1.22; }\n.own-uber .ub-display-lg { font-family: var(--f-display); font-size: clamp(24px, 3.2cqi, 32px); font-weight: 700; line-height: 1.25; }\n.own-uber .ub-display-md { font-family: var(--f-display); font-size: clamp(20px, 2.4cqi, 24px); font-weight: 700; line-height: 1.33; }\n.own-uber .ub-lead { font-size: clamp(16px, 1.5cqi, 18px); font-weight: 500; line-height: 1.5; color: var(--body); }\n.own-uber .ub-body { font-size: 16px; line-height: 1.6; color: var(--body); }\n.own-uber .ub-body-on-dark { font-size: 16px; line-height: 1.6; color: rgba(255,255,255,.72); }\n.own-uber .ub-eyebrow { font-size: 12px; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; color: var(--body); margin-bottom: 12px; }\n.own-uber .ub-eyebrow-on-dark { font-size: 12px; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; color: rgba(255,255,255,.7); margin-bottom: 12px; }\n.own-uber .ub-sec-head { max-width: 640px; margin-bottom: clamp(24px, 4cqi, 40px); }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-uber .ub-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 44px; padding: 12px 20px; border-radius: var(--r-pill);\n  font-size: 16px; font-weight: 500; line-height: 1.25; white-space: nowrap;\n  transition: background-color .15s, transform .15s, box-shadow .15s;\n}\n.own-uber .ub-btn-sm { height: 40px; padding: 10px 16px; font-size: 16px; }\n.own-uber .ub-btn-wide { width: 100%; }\n.own-uber .ub-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-uber .ub-btn-primary:hover { background: var(--black-elevated); }\n.own-uber .ub-btn-primary:active { transform: scale(.98); }\n.own-uber .ub-btn-secondary { background: var(--canvas); color: var(--ink); }\n.own-uber .ub-btn-secondary:hover { background: var(--canvas-soft); }\n.own-uber .ub-btn-subtle { background: var(--canvas-soft); color: var(--ink); }\n.own-uber .ub-btn-subtle:hover { background: var(--surface-pressed); }\n.own-uber .ub-btn-ghost-on-dark { background: transparent; color: var(--on-dark); box-shadow: inset 0 0 0 1px rgba(255,255,255,.4); }\n.own-uber .ub-btn-ghost-on-dark:hover { background: rgba(255,255,255,.12); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-uber .ub-nav { position: sticky; top: 68px; z-index: 40; background: var(--canvas); border-bottom: 1px solid var(--canvas-soft); }\n.own-uber .ub-nav-in { display: flex; align-items: center; gap: 24px; height: 64px; max-width: 1200px; margin: 0 auto; padding: 16px var(--gut); }\n.own-uber .ub-brand { font-family: var(--f-display); font-size: 26px; font-weight: 700; letter-spacing: -.6px; flex: none; }\n.own-uber .ub-nav-links { display: flex; gap: 6px; flex: 1 1 auto; }\n.own-uber .ub-nav-links a { font-size: 16px; font-weight: 500; padding: 8px 12px; border-radius: var(--r-pill); }\n.own-uber .ub-nav-links a:hover { background: var(--canvas-soft); }\n.own-uber .ub-nav-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; }\n.own-uber .ub-burger { display: none; place-items: center; width: 40px; height: 40px; border: 0; border-radius: var(--r-pill); background: var(--canvas-soft); cursor: pointer; }\n.own-uber .ub-burger svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }\n.own-uber .ub-drawer { display: grid; gap: 4px; padding: 12px var(--gut) 16px; border-bottom: 1px solid var(--canvas-soft); background: var(--canvas); }\n.own-uber .ub-drawer a { font-size: 16px; font-weight: 500; padding: 10px 12px; border-radius: var(--r-lg); }\n.own-uber .ub-drawer a:hover { background: var(--canvas-soft); }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-uber .ub-hero { padding: var(--sec) 0 clamp(28px, 4cqi, 48px); }\n.own-uber .ub-hero-in { display: grid; grid-template-columns: 1.1fr .9fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-uber .ub-hero .ub-lead { max-width: 48ch; margin: 20px 0 26px; }\n.own-uber .ub-tabs { display: inline-flex; gap: 4px; padding: 4px; border-radius: var(--r-pill-tab); background: var(--canvas-soft); }\n.own-uber .ub-tab {\n  height: 36px; padding: 0 20px; border: 0; border-radius: var(--r-pill-tab); background: transparent;\n  color: var(--ink); font-size: 16px; font-weight: 500; cursor: pointer;\n}\n.own-uber .ub-tab.on { background: var(--canvas); box-shadow: 0 2px 8px rgba(0,0,0,.16); }\n\n.own-uber .ub-request-card {\n  background: var(--canvas); border-radius: var(--r-xl); padding: 16px;\n  box-shadow: rgba(0,0,0,.16) 0px 4px 16px 0px; display: grid; gap: 10px;\n}\n.own-uber .ub-req-row { display: flex; align-items: center; gap: 12px; background: var(--canvas-soft); border-radius: var(--r-md); padding: 14px 16px; }\n.own-uber .ub-req-ic { display: grid; place-items: center; width: 24px; height: 24px; flex: none; }\n.own-uber .ub-req-ic svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-uber .ub-req-lab { display: block; font-size: 12px; color: var(--body); }\n.own-uber .ub-req-val { display: block; font-size: 16px; font-weight: 500; color: var(--ink); }\n.own-uber .ub-request-card .ub-btn-primary { margin-top: 4px; }\n\n.own-uber .ub-chips { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 32px; }\n.own-uber .ub-chip {\n  display: inline-flex; align-items: center; gap: 8px; padding: 10px 16px; border-radius: var(--r-pill);\n  background: var(--canvas-soft); color: var(--ink); font-size: 14px; font-weight: 500;\n}\n.own-uber .ub-chip svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n\n/* ── sections / promos ───────────────────────────────────────────────── */\n.own-uber .ub-section { padding: var(--sec) 0; }\n.own-uber .ub-promo { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 48px); align-items: center; margin-bottom: clamp(28px, 4cqi, 48px); }\n.own-uber .ub-promo-rev .ub-promo-art { order: 2; }\n.own-uber .ub-promo-art {\n  border-radius: var(--r-xl); overflow: hidden; min-height: 300px; aspect-ratio: 4 / 3;\n  display: grid; place-items: center; padding: 28px;\n}\n.own-uber .ub-art-riders { background: linear-gradient(140deg, #e6e6e6 0%, #f7f7f7 100%); }\n.own-uber .ub-art-drivers { background: linear-gradient(140deg, #ececec 0%, #f5f5f5 100%); }\n.own-uber .ub-art-tile { width: 100%; max-width: 340px; background: var(--canvas); border-radius: var(--r-xl); padding: 22px; box-shadow: 0 16px 40px -28px rgba(0,0,0,.5); }\n.own-uber .ub-art-tile.ub-art-dark { background: var(--ink); color: var(--on-dark); }\n.own-uber .ub-art-tile svg { width: 100%; height: 74px; }\n.own-uber .ub-art-num { display: block; font-family: var(--f-display); font-size: 40px; font-weight: 700; line-height: 1.1; }\n.own-uber .ub-art-lab { display: block; font-size: 13px; color: var(--body); margin: 2px 0 14px; }\n.own-uber .ub-art-dark .ub-art-lab, .own-uber .ub-art-onblack .ub-art-lab { color: rgba(255,255,255,.7); }\n.own-uber .ub-bars { display: flex; align-items: flex-end; gap: 8px; height: 74px; }\n.own-uber .ub-bars i { flex: 1; border-radius: 6px; background: #fff; }\n.own-uber .ub-promo-copy h3 { margin-bottom: 12px; }\n.own-uber .ub-promo-copy .ub-body { max-width: 44ch; margin-bottom: 22px; }\n\n/* ── black mid-page band ─────────────────────────────────────────────── */\n.own-uber .ub-dark-band { background: var(--ink); color: var(--on-dark); padding: var(--sec) 0; }\n.own-uber .ub-dark-in { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-uber .ub-art-dark-illus { border-radius: var(--r-xl); background: rgba(255,255,255,.06); aspect-ratio: 4 / 3; display: grid; place-items: center; padding: 28px; }\n.own-uber .ub-art-onblack { background: var(--black-elevated); color: var(--on-dark); }\n.own-uber .ub-map { position: relative; height: 90px; margin-top: 16px; border-radius: var(--r-md); background: radial-gradient(circle at 40% 50%, rgba(255,255,255,.14), transparent 60%); }\n.own-uber .ub-map-dot { position: absolute; width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 4px rgba(255,255,255,.25); }\n.own-uber .ub-dark-copy .ub-body-on-dark { max-width: 46ch; margin: 18px 0 26px; }\n.own-uber .ub-dark-actions { display: flex; gap: 12px; flex-wrap: wrap; }\n\n/* ── showcase ────────────────────────────────────────────────────────── */\n.own-uber .ub-showcase {\n  position: relative; border-radius: var(--r-xl); overflow: hidden; background: var(--ink); color: var(--on-dark);\n  display: grid; grid-template-columns: 1fr 1fr; align-items: center; min-height: 340px;\n}\n.own-uber .ub-showcase-art {\n  position: absolute; inset: 0; background: linear-gradient(120deg, #1c1c1c 0%, #000 60%);\n  display: grid; place-items: center;\n}\n.own-uber .ub-showcase-year { font-family: var(--f-display); font-size: clamp(90px, 20cqi, 220px); font-weight: 700; color: rgba(255,255,255,.07); line-height: 1; }\n.own-uber .ub-showcase-copy { position: relative; z-index: 2; padding: clamp(28px, 4cqi, 48px); grid-column: 1 / -1; max-width: 560px; }\n.own-uber .ub-display-lg { color: inherit; }\n\n/* ── FAQ ─────────────────────────────────────────────────────────────── */\n.own-uber .ub-faq-wrap { display: grid; grid-template-columns: .8fr 1.2fr; gap: clamp(24px, 4cqi, 56px); align-items: start; }\n.own-uber .ub-faq-head .ub-btn { margin-top: 18px; }\n.own-uber .ub-faq { border-top: 1px solid var(--canvas-soft); }\n.own-uber .ub-faq-item { border-bottom: 1px solid var(--canvas-soft); }\n.own-uber .ub-faq-q {\n  width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 16px;\n  padding: 20px 0; border: 0; background: none; cursor: pointer; text-align: left;\n  font-size: 16px; font-weight: 500; color: var(--ink);\n}\n.own-uber .ub-faq-q svg { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; transition: transform .2s; }\n.own-uber .ub-faq-item.open .ub-faq-q svg { transform: rotate(45deg); }\n.own-uber .ub-faq-a { display: none; padding: 0 0 22px; font-size: 16px; line-height: 1.6; color: var(--body); max-width: 60ch; }\n.own-uber .ub-faq-item.open .ub-faq-a { display: block; }\n\n/* ── downloads ───────────────────────────────────────────────────────── */\n.own-uber .ub-downloads { padding: 0 0 var(--sec); }\n.own-uber .ub-dl-in { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }\n.own-uber .ub-dl-in > div { background: var(--canvas-soft); border-radius: var(--r-xl); padding: 28px; }\n.own-uber .ub-dl-in .ub-display-md { margin-bottom: 16px; }\n.own-uber .ub-app-pill {\n  display: inline-flex; align-items: center; gap: 8px; padding: 12px 24px; border-radius: var(--r-pill);\n  background: var(--ink); color: var(--on-dark); font-size: 16px; font-weight: 500;\n}\n.own-uber .ub-showcase .ub-app-pill { background: #fff; color: var(--ink); }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-uber .ub-foot { background: var(--primary); color: var(--on-dark); padding: clamp(32px, 5cqi, 48px) 0; }\n.own-uber .ub-foot-word { font-family: var(--f-display); font-size: 30px; font-weight: 700; letter-spacing: -.6px; margin-bottom: 26px; }\n.own-uber .ub-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-uber .ub-foot-grid > div { display: flex; flex-direction: column; gap: 10px; }\n.own-uber .ub-foot-head { font-size: 16px; font-weight: 500; margin-bottom: 4px; }\n.own-uber .ub-foot-grid a { font-size: 14px; color: var(--hairline-mid); }\n.own-uber .ub-foot-grid a:hover { color: var(--on-dark); }\n.own-uber .ub-foot-link { color: var(--link); }\n.own-uber .ub-foot-fine { margin-top: 28px; font-size: 12px; color: var(--mute); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-uber .ub-nav-links { display: none; }\n  .own-uber .ub-burger { display: grid; }\n}\n@container frame (max-width: 760px) {\n  .own-uber .ub-hero-in, .own-uber .ub-promo, .own-uber .ub-dark-in,\n  .own-uber .ub-faq-wrap, .own-uber .ub-dl-in, .own-uber .ub-showcase { grid-template-columns: 1fr; }\n  .own-uber .ub-promo-rev .ub-promo-art { order: 0; }\n  .own-uber .ub-foot-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-uber .ub-showcase { min-height: 0; }\n}\n@container frame (max-width: 430px) {\n  .own-uber .ub-nav-actions .ub-btn-secondary { display: none; }\n  .own-uber .ub-dark-actions { flex-direction: column; }\n  .own-uber .ub-dark-actions .ub-btn { width: 100%; }\n  .own-uber .ub-foot-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-uber *, .own-uber *::before, .own-uber *::after {\n    animation-duration: .001ms !important; transition-duration: .001ms !important;\n  }\n}\n"};
/* ══ UBER — Northwind operations analytics ══════════════════════════════════════
   Registers window.OWN_LAYOUTS['uber'].init(root). Renders the quick-start chips
   and FAQ accordion, wires the hero tab toggle and mobile drawer. Returns a
   cleanup that removes every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  var ICONS = {
    pin: 'M12 2a8 8 0 0 0-8 8c0 6 8 12 8 12s8-6 8-12a8 8 0 0 0-8-8Z',
    route: 'M4 12h16M14 6l6 6-6 6',
    clock: 'M12 4a8 8 0 1 0 0 16a8 8 0 0 0 0-16M12 8v4l3 2',
    truck: 'M3 7h11v8H3zM14 10h4l3 3v2h-7zM7 19a1.6 1.6 0 1 0 0-3.2A1.6 1.6 0 0 0 7 19ZM17 19a1.6 1.6 0 1 0 0-3.2A1.6 1.6 0 0 0 17 19Z',
    chart: 'M4 19V9M10 19V5M16 19v-7M3 19h18'
  };

  var CHIPS = [
    { icon: 'pin', label: 'Track a region' },
    { icon: 'route', label: 'Compare routes' },
    { icon: 'clock', label: 'Plan a quarter' },
    { icon: 'truck', label: 'Ship throughput' },
    { icon: 'chart', label: 'Forecast revenue' }
  ];

  var FAQ = [
    { q: 'What is Northwind?', a: 'Northwind is an operations analytics platform. It unifies regions, throughput, and revenue on one ledger so every team reads the same numbers.' },
    { q: 'How is it priced?', a: 'Plans are usage-based. The free tier covers a single region; paid tiers scale by region count and data volume, with no per-seat charge.' },
    { q: 'Can I self-host it?', a: 'Yes. Northwind ships as an open-source core you can run on your own infrastructure, with a managed cloud option when you would rather not.' },
    { q: 'Does it replace our BI tool?', a: 'It sits alongside it. Northwind handles live operations data; your BI stack stays for the long-horizon reporting it already does well.' },
    { q: 'Which regions are supported?', a: 'Six regions today, with new ones added as operations expand. Data residency is configurable per region.' }
  ];

  OWN['uber'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var $ = function (s) { return root.querySelector(s); };
      var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }

      /* chips */
      var chips = $('#ubChips');
      if (chips) {
        chips.innerHTML = CHIPS.map(function (c) {
          return '<a class="ub-chip" href="#">'
            + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + esc(ICONS[c.icon]) + '"/></svg>'
            + esc(c.label) + '</a>';
        }).join('');
      }

      /* FAQ */
      var faq = $('#ubFaq');
      if (faq) {
        faq.innerHTML = FAQ.map(function (f, i) {
          return '<div class="ub-faq-item' + (i === 0 ? ' open' : '') + '">'
            + '<button class="ub-faq-q" type="button" aria-expanded="' + (i === 0) + '">'
            + esc(f.q)
            + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></button>'
            + '<div class="ub-faq-a">' + esc(f.a) + '</div></div>';
        }).join('');
        on(faq, 'click', function (e) {
          var q = e.target.closest('.ub-faq-q');
          if (!q) return;
          var item = q.parentElement;
          var open = item.classList.toggle('open');
          q.setAttribute('aria-expanded', String(open));
        });
      }

      /* hero tabs */
      $$('.ub-tab').forEach(function (t) {
        on(t, 'click', function () {
          $$('.ub-tab').forEach(function (x) {
            var sel = x === t;
            x.classList.toggle('on', sel);
            x.setAttribute('aria-selected', String(sel));
          });
        });
      });

      /* mobile drawer */
      var burger = $('[data-ub-menu]');
      var drawer = $('[data-ub-drawer]');
      on(burger, 'click', function () {
        if (!drawer) return;
        var open = drawer.hidden;
        drawer.hidden = !open;
        burger.setAttribute('aria-expanded', String(open));
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) {} }
      };
    }
  };
})();
